local controller_base = get_or_create_global_variable('Quest/Base/QuestControllerBase')

---@class FireWorldDokkaebiController : QuestControllerBase
local local_class = newclass('FireWorldDokkaebiController', controller_base)

function local_class:init(cs_controller)
	self.super:init(cs_controller)

	-- 사용할 섹션 스크립트 정보. 주석 해제하고 사용
	self.script_config = {
		HasPreSection = true,
		NormalSectionCount = 1,
		HasPostSection = true
	}

	self.scene_version = scene_util.default_version + 1

	self.npc = setmetatable({
		spec = {
			dokkaebi = 'dokkaebi',
			dokkaebi_mini = 'dokkaebi_mini',
			dokkaebi_dragon = 'dokkaebi_dragon',
			doll_girl = 'doll_girl',
			doctor_bear = 'doctor_bear',
			sapa_dragontalon_minion = 'sapa_dragontalon_minion',
		}
	}, {
		__index = function(this, key)
			return get_character(this.spec[key])
		end
	})

	self.get_rock_object = function()
		return get_field_object('sub_dokkaebi_rock')
	end
end

function local_class:load_resource()
end

function local_class:dispose()
	self.super:dispose()
end

function local_class:on_event(e)
	return false
end

function local_class:on_stage_loaded()
end

function local_class:on_stage_end()
end

return local_class
